import { Config } from "@elhadry/tui/config"
import { Schema } from "effect"
import { OPENCODE_VERSION } from "../version"

/** Written into `cli.json`: a schema next to the file, so editors validate without a network round trip. */
export const SchemaURL = "./cli.schema.json"
/** Canonical identifier for the published copy of the same document. */
export const SchemaID = "https://elhadry.ai/v2/cli.json"
export const SchemaFile = "cli.schema.json"
/** Marks the generated file, so another version replaces it and startup skips reserializing it. */
export const SchemaStamp = `Generated by Elhadry Agent ${OPENCODE_VERSION}; do not edit.`
/** The upstream schema URL older configs point at. */
export const LegacySchemaURL = "https://opencode.ai/v2/cli.json"

export const Info = Schema.Struct({
  $schema: Schema.optional(Schema.String).annotate({ description: "JSON Schema for CLI configuration" }),
  ...Config.Info.fields,
})
export type Info = Schema.Schema.Type<typeof Info>

export function jsonSchema() {
  const document = Schema.toJsonSchemaDocument(Info, { onExcessProperty: "error" })
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: SchemaID,
    ...document.schema,
    ...(Object.keys(document.definitions).length ? { $defs: document.definitions } : {}),
    $comment: SchemaStamp,
  }
}

export function normalizeLegacyTabs(info: Info | undefined) {
  if (info?.tabs?.enabled === undefined) return info
  const tabs = { ...info.tabs }
  tabs.mode ??= tabs.enabled ? "on" : "off"
  delete tabs.enabled
  return { ...info, tabs }
}
